template:
struct UserId(pub u64);
struct GroupId(pub u64);

fn grant_access(user: ⟦user_param⟧, group: ⟦group_param⟧) -> bool {
    user.0 != 0 && group.0 != 0
}

fn main() {
    let user = UserId(42);
    let group = GroupId(10);
    println!("{}", grant_access(user, group));
}

tests:
#[test]
fn test_access() {
    assert!(grant_access(UserId(1), GroupId(1)));
    assert!(!grant_access(UserId(0), GroupId(1)));
}
